-- 전국 저수지 목록 (scripts/export_sql.py 로 생성)
-- DB: mysql, 행 수: 14,366
-- 실행하면 reservoirs 테이블을 지우고 새로 만듭니다.
SET NAMES utf8mb4;
DROP TABLE IF EXISTS reservoirs;
CREATE TABLE reservoirs (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  source VARCHAR(20) COMMENT '출처',
  facility_code VARCHAR(30) COMMENT '시설코드(관리번호)',
  name VARCHAR(100) NOT NULL COMMENT '시설명',
  sido VARCHAR(20) COMMENT '시도',
  sigungu VARCHAR(40) COMMENT '시군구',
  address VARCHAR(255) COMMENT '지번주소',
  road_address VARCHAR(255) COMMENT '도로명주소',
  manager VARCHAR(100) COMMENT '관리기관',
  total_storage DECIMAL(14,4) COMMENT '총저수량(천㎥)',
  effective_storage DECIMAL(14,4) COMMENT '유효저수량(천㎥)',
  benefit_area DECIMAL(14,4) COMMENT '수혜면적(ha)',
  basin_area DECIMAL(14,4) COMMENT '유역면적(ha)',
  full_water_area DECIMAL(14,4) COMMENT '만수면적(ha)',
  dam_height DECIMAL(10,2) COMMENT '제당높이(m)',
  dam_length DECIMAL(10,2) COMMENT '제당길이(m)',
  completed_year SMALLINT COMMENT '준공연도',
  latitude DECIMAL(10,7) COMMENT '위도',
  longitude DECIMAL(10,7) COMMENT '경도',
  base_date DATE COMMENT '데이터기준일자'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='전국 저수지 목록';
CREATE INDEX idx_reservoirs_region ON reservoirs (sido, sigungu);
CREATE INDEX idx_reservoirs_name ON reservoirs (name);
START TRANSACTION;
COMMIT;
